type htUVLCEntry struct{ pre, preLen, suf, sufLen, ext, extLen uint8 }

// htUVLCEncTbl mirrors openjph uvlc_init_tables (75 entries).
var htUVLCEncTbl = func() [75]htUVLCEntry {
	var t [75]htUVLCEntry
	t[0] = htUVLCEntry{0, 0, 0, 0, 0, 0}
	t[1] = htUVLCEntry{1, 1, 0, 0, 0, 0}
	t[2] = htUVLCEntry{2, 2, 0, 0, 0, 0}
	t[3] = htUVLCEntry{4, 3, 0, 1, 0, 0}
	t[4] = htUVLCEntry{4, 3, 1, 1, 0, 0}
	for i := 5; i < 33; i++ {
		t[i] = htUVLCEntry{0, 3, uint8(i - 5), 5, 0, 0}
	}
	for i := 33; i < 75; i++ {
		t[i] = htUVLCEntry{0, 3, uint8(28 + (i-33)%4), 5, uint8((i - 33) / 4), 4}
	}
	return t
}()
